pub fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    let len = list.len();
    debug_assert!(len > 0, "list must be non-empty");
    debug_assert!(n > 0 && n < len, "n must satisfy 0 < n < list.len()");

    let mut out = Vec::with_capacity(len);
    out.extend_from_slice(&list[n..]);
    out.extend_from_slice(&list[..n]);
    out
}